<?php
declare(strict_types=1);

/** Curated from applicant page labels. Contains instructions, never profile values. */
function aics_chatbot_portal_help(): array
{
    return [
        'portal_navigation' => ['title' => 'Applicant menu guide', 'facts' => 'The applicant sidebar has these exact tabs: Overview Dashboard, My Profile, Submit Application, Documents, Application Status, Manage Applications, Notifications. Application Status is the tab for viewing application progress. There is no tab called Your Application List or My Applications. My applications is a chatbot shortcut, not a sidebar tab. Overview Dashboard shows Your Latest Application and Track Detailed Status. Use the sidebar menu toggle if the menu is collapsed.'],
        'portal_status' => ['title' => 'Application Status tutorial', 'page' => 'application-status.php', 'label' => 'Open Application Status', 'facts' => 'To see an application: open the sidebar, select Application Status, and find the application reference you want to check. Overview Dashboard also has Your Latest Application and Track Detailed Status. Seeing an existing application does not require waiting for the application cooldown.'],
        'portal_profile' => ['title' => 'My Profile tutorial', 'page' => 'my-profile.php', 'label' => 'Open My Profile', 'facts' => 'Open My Profile in the sidebar. Find Update My Information. Change the required details, then press Save and check the save feedback. First Name and Last Name: enter your own names as recorded in your identification. Middle Name is optional. Extension Name is optional, for example Jr., Sr., III; leave blank if none. Date of Birth: select your actual birth date. Age is calculated and read-only. Civil Status: choose the matching option; if Other is chosen, fill Specify Civil Status. Highest Educational Attainment: select your highest education level. Phone Number: enter an active Philippine mobile number, e.g. 09XXXXXXXXX (digits, not the literal X characters); +639 format is also supported. Email Address is optional. Occupation / Source of Income: select the matching option; if Other, fill Specify Occupation / Source of Income. Estimated Monthly Income: choose the matching range, not an assistance amount. Address uses Municipality, Barangay, Province and optional House No. / Street / Sitio / Purok. Complete Address is assembled from address fields. Do not ask the user to paste their personal details in chat; guide them to type in the form. Saving a profile must not be described as changing an already submitted application.'],
        'portal_documents' => ['title' => 'Documents tutorial', 'page' => 'documents.php', 'label' => 'Open Documents', 'facts' => 'Open Documents in the sidebar to see files submitted with applications. To replace or update a file for an editable application, use Manage Applications, then Edit Application. Do not instruct the user to upload directly in Documents or claim all applications remain editable.'],
        'portal_manage' => ['title' => 'Manage Applications tutorial', 'page' => 'cancel-request.php', 'label' => 'Open Manage Applications', 'facts' => 'Open Manage Applications. Find the correct application. Use Edit Application only when available; update the information or attachments and follow the form confirmation. Cancel Application is available only for eligible applications and requires confirmation. Locked applications are read-only. Do not promise that editing or cancellation is available without checking what the page shows. Contact PSWDO when an application is locked and needs correction.'],
        'portal_submit' => ['title' => 'Submit Application tutorial', 'page' => 'submit-request.php', 'label' => 'Open Submit Application', 'facts' => 'Complete My Profile first, then open Submit Application. Enter truthful applicant and beneficiary details in the corresponding fields. Beneficiary Category should describe the beneficiary, not the assistance type. In Describe the beneficiary\'s problem / present need, briefly explain the actual situation, help needed, and relevant facts without inventing a diagnosis. For example use placeholders: The beneficiary needs help with [actual need] because [actual situation]. Fill family details as applicable, select the assistance type, follow Next, supply the required files displayed, review the form, and confirm Yes, Submit Now. Required fields are marked. Do not invent facts for the user. Existing cooldown or validation can prevent a new submission; it does not prevent viewing old applications.'],
        'portal_notifications' => ['title' => 'Notifications tutorial', 'page' => 'notifications.php', 'label' => 'Open Notifications', 'facts' => 'Open Notifications in the sidebar to read recorded application updates. Check Application Status for current progress. Do not promise an SMS delivery time.'],
    ];
}
